import { Outlet, Link, useLocation } from 'react-router-dom';
import { Header, Footer, LoginModal, ThemeToggle } from '@cloistr/ui/components';
import { useSignerAuth } from '../hooks/useSignerAuth';
import { useFrostCosignListener } from '../hooks/useFrostCosignListener';
import { FrostCosignApprovalModal } from './FrostCosignApprovalModal';
import { useQuery } from '@tanstack/react-query';
import apiClient from '../api/client';

/**
 * Navigation links for the signer
 */
const NAV_LINKS = [
  { path: '/dashboard', label: 'Dashboard' },
  { path: '/keys', label: 'Keys' },
  { path: '/requests', label: 'Requests' },
  { path: '/apps', label: 'Apps' },
  { path: '/frost', label: 'FROST' },
  { path: '/settings', label: 'Settings' },
];

/**
 * Main application layout with header, navigation, and footer
 */
export function Layout() {
  const location = useLocation();
  const { isAuthenticated, user, logout, showLoginModal, hideLoginModal, loginModalOpen, loginWithSession } = useSignerAuth();

  // FROST cosign listener - runs whenever the user is logged in and has
  // at least one FROST key with a locally stored share. Collects
  // incoming cosign requests, renders the approval modal for the
  // head of the queue.
  const { data: keys } = useQuery({
    queryKey: ['keys'],
    queryFn: () => apiClient.listKeys(),
    enabled: isAuthenticated,
  });
  const frostRelays = Array.from(
    new Set(
      (keys ?? [])
        .filter((k) => k.key_type === 'frost-user')
        .flatMap((k) => k.relays ?? []),
    ),
  );
  const { queue: cosignQueue, dismissHead: dismissCosignHead } = useFrostCosignListener({
    relays: frostRelays,
    enabled: isAuthenticated && frostRelays.length > 0,
  });

  return (
    <div className="app-layout">
      {/* Shared Cloistr navbar (service menu + auth). The signer manages its own
          JWT session (bootstrapped from Nostr), so we feed the Header explicit
          auth state instead of letting it use the Nostr context. */}
      {/* ThemeToggle lives in the persistent header so it is always reachable,
          even before the user authenticates.  Previously it sat inside the
          auth-gated sub-header nav, making it inaccessible on the sign-in
          screen.  The Header accepts children in its right-side slot. */}
      <Header
        activeServiceId="signer"
        auth={{
          authenticated: isAuthenticated,
          pubkey: user?.pubkey,
          onLogout: logout,
          onSignIn: showLoginModal,
        }}
      >
        <ThemeToggle />
      </Header>

      {/* Sub-header nav strip - only show when authenticated */}
      {isAuthenticated && (
        <nav className="app-subheader">
          {NAV_LINKS.map((link) => (
            <Link
              key={link.path}
              to={link.path}
              className={`app-subheader-link ${location.pathname === link.path ? 'active' : ''}`}
            >
              {link.label}
            </Link>
          ))}
          {user?.is_admin && (
            <Link
              to="/users"
              className={`app-subheader-link ${location.pathname === '/users' ? 'active' : ''}`}
            >
              Users
            </Link>
          )}
        </nav>
      )}

      {/* Main Content */}
      <div className="app-main">
        <main className="app-content">
          {isAuthenticated ? (
            <Outlet />
          ) : (
            <div className="welcome-screen">
              <div className="welcome-content">
                <h1>Welcome to Cloistr Signer</h1>
                <p>
                  Secure remote signing for Nostr. Manage your keys, authorize apps,
                  and sign events from any device.
                </p>
                <button className="btn btn-primary btn-lg" onClick={showLoginModal}>
                  Get Started
                </button>
              </div>
            </div>
          )}
        </main>
      </div>

      <Footer />

      {/* Login Modal */}
      <LoginModal
        isOpen={loginModalOpen}
        onClose={hideLoginModal}
        signerUrl="https://signer.cloistr.xyz"
        mode="session"
        onSession={loginWithSession}
      />

      {/* FROST cosign approval modal — shows the head of the queue when
          the listener has pending requests. */}
      {cosignQueue.length > 0 && (
        <FrostCosignApprovalModal
          handle={cosignQueue[0]}
          onDismiss={dismissCosignHead}
        />
      )}
    </div>
  );
}
