/**
 * Signer authentication hook
 *
 * Combines:
 * 1. Nostr auth from SharedAuthProvider (NIP-07/NIP-46)
 * 2. Signer backend JWT auth (for API access)
 *
 * Flow:
 * - User authenticates via Nostr OR username/password
 * - Signer backend issues JWT for API access
 * - JWT stored in localStorage
 */

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  useMemo,
  type ReactNode,
} from 'react';
// Import useNostrAuth from @cloistr/auth (the singleton peer), NOT from
// @cloistr/collab-common. collab-common vendors its OWN copy of @cloistr/auth,
// so its useNostrAuth reads a different AuthContext than the one @cloistr/ui's
// SharedAuthProvider populates (which uses the @cloistr/auth singleton) — the
// mismatch threw "useNostrAuth must be used within an AuthProvider".
import { useNostrAuth } from '@cloistr/auth';
import apiClient from '../api/client';
import { unlockShareStorage, lockShareStorage } from '../lib/frostStorage';
import type { User, LoginRequest, RegisterRequest } from '../types/api';

// ============================================
// Types
// ============================================

export interface SignerAuthState {
  /** Authenticated user from signer backend */
  user: User | null;
  /** JWT token for API access */
  token: string | null;
  /** Loading state */
  loading: boolean;
  /** Error message */
  error: string | null;
}

export interface SignerAuthContextValue extends SignerAuthState {
  /** Login with username and password */
  loginWithPassword: (data: LoginRequest) => Promise<void>;
  /** Register new account with username/password */
  register: (data: RegisterRequest) => Promise<void>;
  /** Logout and clear session */
  logout: () => Promise<void>;
  /** Whether user is authenticated with signer backend */
  isAuthenticated: boolean;
  /** Clear error state */
  clearError: () => void;
  /** Show login modal */
  showLoginModal: () => void;
  /** Hide login modal */
  hideLoginModal: () => void;
  /** Whether login modal is visible */
  loginModalOpen: boolean;
  /** Hydrate auth state from an externally-obtained session (e.g. LoginModal mode=session) */
  loginWithSession: (data: { token: string; expiresAt: string; user: unknown; password: string; username: string }) => Promise<void>;
  /**
   * Step-up gate for sensitive/destructive actions. Resolves true immediately
   * when already fully authenticated (local JWT + FROST unlocked). In a
   * view-only shared-session (sessionMode), opens the login modal to re-auth
   * (password/OTP/passkey per the login flow) and resolves true once full auth
   * is established, or false if the user cancels. Callers must gate destructive
   * ops: `if (!(await requireFullAuth())) return;`
   */
  requireFullAuth: () => Promise<boolean>;
}

// ============================================
// Context
// ============================================

const SignerAuthContext = createContext<SignerAuthContextValue | null>(null);

// ============================================
// Storage keys
// ============================================

const STORAGE_KEYS = {
  TOKEN: 'signer:token',
  TOKEN_EXPIRY: 'signer:tokenExpiry',
  USER: 'signer:user',
} as const;

// ============================================
// Provider
// ============================================

interface SignerAuthProviderProps {
  children: ReactNode;
}

export function SignerAuthProvider({ children }: SignerAuthProviderProps) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [loginModalOpen, setLoginModalOpen] = useState(false);
  // True when authenticated purely via the shared .cloistr.xyz signer session
  // cookie (no local JWT + no FROST unlock). Grants VIEWING; destructive key
  // operations must step up (password/OTP) to unlock FROST — see Option B.
  const [sessionMode, setSessionMode] = useState(false);
  // Resolver for an in-flight step-up (requireFullAuth) awaiting the login modal.
  const stepUpResolverRef = useRef<((ok: boolean) => void) | null>(null);

  // Nostr auth from SharedAuthProvider
  const { authState: nostrAuth } = useNostrAuth();

  // ==========================================
  // Token management
  // ==========================================

  const saveAuthState = useCallback((newToken: string, expiresAt: string, newUser: User) => {
    localStorage.setItem(STORAGE_KEYS.TOKEN, newToken);
    localStorage.setItem(STORAGE_KEYS.TOKEN_EXPIRY, expiresAt);
    localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(newUser));
    setToken(newToken);
    setUser(newUser);
    apiClient.setToken(newToken);
    setLoginModalOpen(false);
  }, []);

  const clearAuthState = useCallback(() => {
    localStorage.removeItem(STORAGE_KEYS.TOKEN);
    localStorage.removeItem(STORAGE_KEYS.TOKEN_EXPIRY);
    localStorage.removeItem(STORAGE_KEYS.USER);
    setToken(null);
    setUser(null);
    setSessionMode(false);
    apiClient.setToken(null);
  }, []);

  // ==========================================
  // Auth methods
  // ==========================================

  const loginWithPassword = useCallback(async (data: LoginRequest) => {
    setLoading(true);
    setError(null);

    try {
      const response = await apiClient.login(data);
      saveAuthState(response.token, response.expires_at, response.user);
      // Derive the FROST-share KEK from the password the user just typed.
      // The KEK lives in module-scoped memory only; the password is
      // forgotten after derivation. Failure here is non-fatal for login
      // (a user without FROST keys never notices); we log + continue.
      try {
        await unlockShareStorage(data.password, response.user.id);
      } catch (unlockErr) {
        console.warn('FROST share storage unlock failed', unlockErr);
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, [saveAuthState]);

  const register = useCallback(async (data: RegisterRequest) => {
    setLoading(true);
    setError(null);

    try {
      const response = await apiClient.register(data);
      saveAuthState(response.token, response.expires_at, response.user);
      // Same KEK-derivation as loginWithPassword. The fresh user's
      // IndexedDB has no shares yet, but generating the salt now means
      // the first storeShare() call is faster.
      try {
        await unlockShareStorage(data.password, response.user.id);
      } catch (unlockErr) {
        console.warn('FROST share storage unlock failed', unlockErr);
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Registration failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, [saveAuthState]);

  const logout = useCallback(async () => {
    try {
      await apiClient.logout();
    } catch {
      // Ignore logout errors
    }
    // Drop the KEK from memory BEFORE clearing auth state. Order matters:
    // a malicious logout race could otherwise still see the KEK active.
    lockShareStorage();
    clearAuthState();
  }, [clearAuthState]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  const showLoginModal = useCallback(() => {
    setLoginModalOpen(true);
  }, []);

  const hideLoginModal = useCallback(() => {
    setLoginModalOpen(false);
    setError(null);
    // If a step-up was awaiting this modal and it's dismissed without full
    // auth, resolve it as cancelled.
    if (stepUpResolverRef.current) {
      stepUpResolverRef.current(false);
      stepUpResolverRef.current = null;
    }
  }, []);

  // Step-up gate. Full auth = local JWT present AND not view-only sessionMode
  // (FROST unlocked). Otherwise open the login modal and await completion.
  const requireFullAuth = useCallback(async (): Promise<boolean> => {
    if (token && !sessionMode) return true;
    setLoginModalOpen(true);
    return new Promise<boolean>((resolve) => {
      stepUpResolverRef.current = resolve;
    });
  }, [token, sessionMode]);

  // Resolve an in-flight step-up once full auth is established (login sets a
  // JWT and clears sessionMode).
  useEffect(() => {
    if (stepUpResolverRef.current && token && !sessionMode) {
      stepUpResolverRef.current(true);
      stepUpResolverRef.current = null;
    }
  }, [token, sessionMode]);

  const loginWithSession = useCallback(async (data: {
    token: string;
    expiresAt: string;
    user: unknown;
    password: string;
    username: string;
  }) => {
    const user = data.user as User;
    saveAuthState(data.token, data.expiresAt, user);
    try {
      await unlockShareStorage(data.password, user.id);
    } catch (unlockErr) {
      console.warn('FROST share storage unlock failed', unlockErr);
    }
  }, [saveAuthState]);

  // ==========================================
  // Sync Nostr auth to signer backend
  // ==========================================

  useEffect(() => {
    // When user connects via Nostr, try to authenticate with signer backend
    if (nostrAuth.isConnected && nostrAuth.pubkey && !token) {
      // TODO: Implement Nostr -> Signer JWT exchange
      // This requires a backend endpoint that:
      // 1. Accepts a signed challenge (NIP-98 style)
      // 2. Creates/finds user by pubkey
      // 3. Returns JWT
      //
      // For now, we still require password login
      // The Nostr connection can be used for key operations
    }
  }, [nostrAuth.isConnected, nostrAuth.pubkey, token]);

  // ==========================================
  // Initialize from storage
  // ==========================================

  useEffect(() => {
    const initAuth = async () => {
      setLoading(true);

      try {
        const storedToken = localStorage.getItem(STORAGE_KEYS.TOKEN);
        const storedExpiry = localStorage.getItem(STORAGE_KEYS.TOKEN_EXPIRY);
        const storedUser = localStorage.getItem(STORAGE_KEYS.USER);

        const tokenUsable =
          storedToken && storedExpiry && storedUser && new Date() < new Date(storedExpiry);

        if (tokenUsable) {
          // Full local session (JWT + FROST unlocked earlier). Validate it.
          apiClient.setToken(storedToken);
          try {
            const currentUser = await apiClient.getMe();
            setToken(storedToken);
            setUser(currentUser);
            return;
          } catch {
            // Stored token invalid — fall through to the shared session probe.
          }
        }

        // No usable local JWT. Recognize the shared .cloistr.xyz signer session
        // cookie so signer's own UI doesn't demand a fresh password when you're
        // already signed in across the suite. getMe() rides the cookie
        // (apiClient always sends credentials:'include'). This is VIEW-ONLY:
        // FROST shares stay locked (no password derived), so destructive key
        // operations must step up to re-auth (Option B) before they can run.
        clearAuthState();
        try {
          apiClient.setToken(null);
          const sessionUser = await apiClient.getMe();
          setUser(sessionUser);
          setSessionMode(true);
        } catch {
          // No shared session either — stay logged out (welcome screen).
        }
      } finally {
        setLoading(false);
      }
    };

    initAuth();
  }, [clearAuthState]);

  // ==========================================
  // Context value
  // ==========================================

  const value = useMemo<SignerAuthContextValue>(() => ({
    user,
    token,
    loading,
    error,
    loginWithPassword,
    register,
    logout,
    isAuthenticated: (!!token || sessionMode) && !!user,
    clearError,
    showLoginModal,
    hideLoginModal,
    loginModalOpen,
    loginWithSession,
    requireFullAuth,
  }), [
    user,
    token,
    sessionMode,
    requireFullAuth,
    loading,
    error,
    loginWithPassword,
    register,
    logout,
    clearError,
    showLoginModal,
    hideLoginModal,
    loginModalOpen,
    loginWithSession,
  ]);

  return (
    <SignerAuthContext.Provider value={value}>
      {children}
    </SignerAuthContext.Provider>
  );
}

// ============================================
// Hook
// ============================================

export function useSignerAuth(): SignerAuthContextValue {
  const context = useContext(SignerAuthContext);
  if (!context) {
    throw new Error('useSignerAuth must be used within SignerAuthProvider');
  }
  return context;
}
